///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/submitprsnm.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearchBeginIndex_ajaxsubmit
 * @description fn Search Begin Index ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchBeginIndex_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearchBeginIndex_ajaxsubmit",
        method: "post",
        action: "/common/submitprsnm.do",
        ref: "dma_fnSearchBeginIndexAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchInit = function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearch = function () {
    const searchForm = $('#searchForm');
    const gubun = ($c.util.getComponent("dma_fnSearchAjaxsubmitReq").get("gubun") || '');
    if (gubun === '') {
        $c.util.getComponent("ipt_beginIndex").setValue("");
    }
    $c.util.getComponent("ipt_submitPersonNm").setValue(encodeURI(document.searchForm.find('input:text[name=ipt_submitPersonNmTmp]').val()));
    document.searchForm.ajaxSubmit({ ajaxUrl: '/common/submitprsnm.do', ajaxCallBack: scwin.fnSearchCallBack });
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
};

/**
 * @method
 * @name fnSearchBeginIndex
 * @description fn Search Begin Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchBeginIndex = function () {
    const searchForm = $('#searchForm');
    $c.util.getComponent("ipt_submitPersonNmTmp").setValue("");
    $c.util.getComponent("ipt_submitPersonNm").setValue("");
    document.searchForm.ajaxSubmit({ ajaxUrl: '/common/submitprsnm.do', ajaxCallBack: scwin.fnSearchCallBack });
};

/**
 * @method
 * @name setSubmitPersonInfo
 * @description set Submit Person Info 처리
 * @param {*} submitOblgAbbrv submitOblgAbbrv
 * @param {*} fssUnqNo fssUnqNo
 * @param {String} disclsSubmitprnTpCd disclsSubmitprnTpCd
 * @param {String} submitOblgNm submitOblgNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSubmitPersonInfo = async function (submitOblgAbbrv, fssUnqNo, disclsSubmitprnTpCd, submitOblgNm) {
    try {
        (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setSubmitPersonInfo === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setSubmitPersonInfo(submitOblgAbbrv, fssUnqNo, disclsSubmitprnTpCd, submitOblgNm) : void 0), $c.win.closePopup([submitOblgAbbrv, fssUnqNo, disclsSubmitprnTpCd, submitOblgNm]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jlddst60203' });
        await $c.win.alert("<ERROR>\n\n" + "비정상적으로 열려진 팝업창입니다. \n\n");
    }
};
